 "content": "def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0 = min(y for y, x in cells)
            c0 = min(x for y, x in cells)
            shape = frozenset((y-r0, x-c0) for y, x in cells)
            out.append((color, cells, shape))
    return out

def transform(grid):
    result = [row[:] for row in grid]
    objects = _components(grid)
    templates = {}
    for color, cells, shape in objects:
        if color != 1:
            templates.setdefault(shape, color)
    for color, cells, shape in objects:
        if color == 1 and shape in templates:
            new_color = templates[shape]
            for r, c in cells:
                result[r][c] = new_color
    return result
